      "rank": 1,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Francis Halzen"
      ],
      "assessment": {
        "nobel_worthiness": "Opening high-energy neutrino astronomy created a new observational channel on the extreme Universe and is a landmark in astroparticle physics.",
        "attribution": "Halzen's leadership in conceiving and building IceCube and establishing the discovery is substantial and unusually clear for a large collaboration.",
        "maturity": "The detector has operated for years, with follow-up observations and a growing body of astrophysical results.",
        "uncertainties": [
          "Credit for a major observatory necessarily extends beyond one individual, though the proposed discovery is tightly associated with Halzen's leadership."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Michel Della Negra",
        "Peter Jenni",
        "Tejinder Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The detector work that made the Higgs-boson discovery possible is a foundational experimental achievement in particle physics.",
        "attribution": "These leaders represent the design, construction, and scientific stewardship of ATLAS and CMS; their roles were decisive, though the work depended on thousands of collaborators.",
        "maturity": "The Higgs discovery has been independently established and its properties continue to be measured with increasing precision.",
        "uncertainties": [
          "A prize would need to recognize detector and collaboration leadership without implying that three people alone built or operated the experiments."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page Jr."
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precision mapping of the cosmic microwave background transformed cosmology into a quantitative field and constrained the Universe's age, composition, and history.",
        "attribution": "The proposed names capture scientific leadership and key contributions to the mission and its analysis, while the result depended on a broad team.",
        "maturity": "The measurements have been extensively checked and complemented by later CMB missions.",
        "uncertainties": [
          "The boundary between WMAP's distinctive achievement and the broader development of precision CMB cosmology is not sharp."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Alfred Y. Cho",
        "Federico Capasso",
        "Jérôme Faist"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum cascade laser introduced a distinct semiconductor laser principle and became a versatile source across important infrared and terahertz applications.",
        "attribution": "Cho and Capasso's invention and Faist's key experimental realization make a strong attribution case across the central early work.",
        "maturity": "The device concept has been reproduced, improved, and used in spectroscopy and sensing for decades.",
        "uncertainties": [
          "The most appropriate balance of credit between the original concept, first demonstration, and subsequent engineering is open to judgment."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Kam-Biu Luk",
        "Soo-Bong Kim",
        "Yifang Wang"
      ],
      "assessment": {
        "nobel_worthiness": "Measuring a nonzero theta-13 established an important part of the neutrino-mixing picture and enabled the current program of precision neutrino physics.",
        "attribution": "The named leaders are closely associated with the reactor experiments that made the decisive disappearance measurements, although the evidence came from large collaborations.",
        "maturity": "The result was independently confirmed by multiple reactor experiments and has supported a sustained program of measurements.",
        "uncertainties": [
          "The distinction between leadership credit and the many essential contributions across the reactor collaborations deserves care."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B053",
      "proposed_laureates": [
        "Christopher Thompson",
        "Chryssa Kouveliotou",
        "Robert C. Duncan"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetars are a striking class of compact object whose extreme magnetic fields have reshaped understanding of neutron stars and high-energy transients.",
        "attribution": "The proposed names span influential theoretical prediction and the observational identification of magnetars.",
        "maturity": "Many sources and outbursts have since supported the magnetar interpretation, making this a well-established astrophysical picture.",
        "uncertainties": [
          "The discovery developed through several observations and theoretical steps, so the boundary of the prize-worthy contribution is debatable."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B050",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks brought unprecedented stability and accuracy to timekeeping and opened new precision tests of fundamental physics.",
        "attribution": "Katori and Ye made complementary, pioneering contributions to the lattice-clock approach and its leading experimental realizations.",
        "maturity": "The technique is established across laboratories, with sustained progress in accuracy and applications.",
        "uncertainties": [
          "The field's rapid development and multiple clock architectures make the historical scope of a single prize difficult to delimit."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Maura McLaughlin",
        "Michael Kramer",
        "Richard N. Manchester"
      ],
      "assessment": {
        "nobel_worthiness": "A gravitational-wave background at nanohertz frequencies would open a major new window on the Universe and on populations of massive black-hole binaries.",
        "attribution": "The named leaders represent important pulsar-timing efforts, but the claimed signal rests on data and analysis from broad, partly independent collaborations.",
        "maturity": "The evidence is compelling and has appeared across several pulsar timing arrays, but interpretation and confirmation remain in progress.",
        "uncertainties": [
          "The signal's source population and the degree to which current evidence establishes a gravitational-wave background remain unsettled.",
          "A clear individual attribution is difficult for a result that depends on long-running international collaborations."
        ]
      }
    }
  ]
